 else: m=(crop[:,:,0]>115)&(crop[:,:,1]>55)&(crop[:,:,0]>crop[:,:,1]*1.2)&(crop[:,:,2]<90)
 H,W=m.shape;seen=np.zeros_like(m); comps=[]
 for yy in range(H):
  for xx in range(W):
   if not m[yy,xx] or seen[yy,xx]: continue
   stack=[(yy,xx)];seen[yy,xx]=1;pts=[]
   while stack:
    y,x=stack.pop();pts.append((y,x))
    for dy in (-1,0,1):
     for dx in (-1,0,1):
      ny,nx=y+dy,x+dx
