   if len(pts)>=3:
    a=np.array(pts); comps.append((len(pts),round(float(a[:,1].mean()+x0),1),round(float(a[:,0].mean()+y0),1),(int(a[:,1].min()+x0),int(a[:,0].min()+y0),int(a[:,1].max()+x0),int(a[:,0].max()+y0))))
